import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over' | 'archived';

interface Project {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' | 'default' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  over: { label: 'Превышение', tone: 'danger' },
  archived: { label: 'В архиве', tone: 'default' },
};

const STATUSES = Object.keys(STATUS_META) as ProjectStatus[];

const PAGE_SIZE = 5;

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекстная библиотека', used: 820, quota: 1000, status: 'active' },
  { id: 'p2', name: 'Аналитика запросов', used: 430, quota: 1000, status: 'active' },
  { id: 'p3', name: 'Миграция биллинга', used: 1180, quota: 1000, status: 'over' },
  { id: 'p4', name: 'Портал поддержки', used: 250, quota: 800, status: 'paused' },
  { id: 'p5', name: 'Мобильный клиент', used: 640, quota: 900, status: 'active' },
  { id: 'p6', name: 'Отчёты для финансов', used: 90, quota: 600, status: 'archived' },
  { id: 'p7', name: 'Индексация документов', used: 710, quota: 750, status: 'active' },
  { id: 'p8', name: 'Экспорт в хранилище', used: 520, quota: 500, status: 'over' },
  { id: 'p9', name: 'Витрина метрик', used: 140, quota: 700, status: 'paused' },
  { id: 'p10', name: 'Каталог интеграций', used: 380, quota: 1200, status: 'archived' },
  { id: 'p11', name: 'Песочница экспериментов', used: 270, quota: 400, status: 'active' },
  { id: 'p12', name: 'Обновление поиска', used: 610, quota: 650, status: 'paused' },
];

export default function ProjectSpendPanel() {
  const [selected, setSelected] = useState<ProjectStatus[]>(STATUSES);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () => PROJECTS.filter((project) => selected.includes(project.status)),
    [selected],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const rows = visible.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: ProjectStatus) => {
    setSelected((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setSelected(STATUSES);
    setPage(1);
  };

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUSES.map((status) => {
          const isActive = selected.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      <JxDivider label="Расход по проектам" />

      {rows.length === 0 ? (
        <JxEmptyState
          title="Проектов не нашлось"
          message="Ни один проект не подходит под выбранные статусы."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul style={{ listStyle: 'none', margin: 0, padding: 0 }}>
            {rows.map((project) => {
              const meta = STATUS_META[project.status];
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '12px',
                    padding: '12px 0',
                    borderBottom: '1px solid var(--jx-rule)',
                  }}
                >
                  <JxProgressCircle value={project.used} max={project.quota} showValue />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ color: 'var(--jx-text)' }}>{project.name}</div>
                    <div style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-mono)' }}>
                      {project.used} / {project.quota}
                    </div>
                  </div>
                  <JxBadge tone={meta.tone} dot>
                    {meta.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

